mapper.select:
SELECT  FROM media_song song 
WHERE song.id > #{cursor}
AND song.source_id=#{sourceId}
ORDER BY song.id LIMIT #{limit}

SELECT  FROM media_song song 
WHERE song.id IN #{id}
ORDER BY song.id

SELECT 
FROM (SELECT song.id, song.scanned_at FROM media_song song

  ORDER BY song.scanned_at DESC, song.id ASC LIMIT #{limit} OFFSET #{offset}
) page_ids JOIN media_song song ON song.id = page_ids.id

ORDER BY page_ids.scanned_at DESC, page_ids.id ASC
